    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


def recoverable_move_error(error, message):
    """A delayed supplier response can make its returned offer ID stale before we accept it."""
    return error.status == 409 or (
        error.status == 422
        and message.get("action", {}).get("type") == "accept"
        and "not a standing offer" in str(error.detail)
    )


