    threads = {"A": [mail(20)], "B": [mail(18)]}
    agent = HybridAgent()
    for decision in agent.decide_many(case, threads):
        for sheet in decision["message"].get("term_sheets", []):
            assert total_cost(case, sheet["terms"]) < total_cost(case, {"unit_price": 18})


