    case["buyer"]["must_haves"] = [{"field": "payment_days", "op": ">=", "value": 45}]
    assert not valid(case, {"unit_price": 20}, {"payment_days": None})
    assert valid(case, {"unit_price": 20, "payment_days": 60})
